INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('49208096-da61-4368-9311-7f68034f6a7e', '0b8ddab7-b106-4873-bc4d-3987421d265d', 6, 'A Caridade Ordinária', NULL, '{"intro": "O amor se prova na paci\u00eancia com quem est\u00e1 ao nosso lado.", "prayer": "Pe\u00e7a para ver Cristo no pr\u00f3ximo.", "practice": "Fa\u00e7a um elogio sincero a algu\u00e9m que convive com voc\u00ea.", "reflection": "N\u00e3o espere grandes ocasi\u00f5es para amar.", "journal_prompt": "Quem voc\u00ea amou hoje de forma concreta?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;